// Expo config plugin: make every native target in the generated Xcode project agree on
// the signing team and the version numbers — including the widget extension.
//
// WHY THIS EXISTS
//
// `/ios` is gitignored and regenerated by `expo prebuild`, so hand-edits do not survive.
// Until this plugin existed, DEVELOPMENT_TEAM had to be re-applied by hand with a
// `perl -pi -e` after every prebuild (see .claude/skills/ios-device-build/), and forgetting
// it broke device builds on signing. Three separate gaps are closed here:
//
//  1. Core Expo's `withDevelopmentTeam` (driven by app.json `ios.appleTeamId`) writes
//     DEVELOPMENT_TEAM to every native target that exists *when it runs*. Because mods run
//     last-registered-first and the built-in iOS plugins are registered after the user's,
//     it runs BEFORE expo-widgets creates `ExpoWidgetsTarget`. It therefore never reaches
//     the extension.
//  2. expo-widgets does set DEVELOPMENT_TEAM on the extension — but only in
//     `addXCConfigurationList`, which early-returns if the target already exists. On any
//     prebuild over an existing `ios/` directory the extension keeps whatever it had.
//  3. Neither sets CODE_SIGN_STYLE, so the extension inherits no explicit signing style.
//
// This plugin runs after all of them (it is listed FIRST in app.json `plugins`, which under
// Expo's LIFO mod chaining means it executes LAST) and simply asserts the correct values on
// every native target. It is idempotent and safe to re-run.
//
// It also pins MARKETING_VERSION / CURRENT_PROJECT_VERSION on every target. The extension's
// Info.plist is generated (GENERATE_INFOPLIST_FILE=YES) from exactly those two settings,
// while the app target's Info.plist gets literal values from app.json. If the two disagree,
// the App Store upload is rejected with "The value of CFBundleVersion in your extension must
// match the app's" — after a full archive, which is the expensive way to learn it.

const { withXcodeProject, IOSConfig } = require('expo/config-plugins');

/** Targets Xcode expects to be signed. Pods aggregate targets must be left alone. */
const SIGNABLE_PRODUCT_TYPES = new Set([
  'com.apple.product-type.application',
  'com.apple.product-type.app-extension',
  'com.apple.product-type.watchkit2-app',
  'com.apple.product-type.bundle.unit-test',
  'com.apple.product-type.bundle.ui-testing',
]);

function unquote(value) {
  if (typeof value !== 'string') return value;
  return value.replace(/^"(.*)"$/, '$1');
}

/**
 * @param {import('expo/config-plugins').ConfigPlugin} _
 */
const withSigningAndVersioning = (config, props = {}) => {
  const appleTeamId = props.appleTeamId ?? config.ios?.appleTeamId;
  const marketingVersion = props.version ?? config.ios?.version ?? config.version;
  const buildNumber = props.buildNumber ?? config.ios?.buildNumber;

  if (!appleTeamId) {
    throw new Error(
      'with-signing-and-versioning: no Apple team id.\n' +
        'Set expo.ios.appleTeamId in app.json (it is "K4MBJGZLNY" for Bundles), or pass\n' +
        '{ appleTeamId } as a plugin option. Without it every device and archive build fails\n' +
        'on signing, which is the failure this plugin exists to prevent.'
    );
  }

  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const targets = IOSConfig.Target.getNativeTargets(project);
    const touched = [];

    for (const [targetUuid, target] of targets) {
      if (!SIGNABLE_PRODUCT_TYPES.has(unquote(target.productType))) continue;

      const configurations = IOSConfig.XcodeUtils.getBuildConfigurationsForListId(
        project,
        target.buildConfigurationList
      );

      for (const [, buildConfig] of configurations) {
        const settings = buildConfig.buildSettings;
        settings.DEVELOPMENT_TEAM = appleTeamId;
        // Automatic is what the ios-device-build flow relies on; Xcode's GUI registers the
        // App Group + Push App IDs and the command line then reuses those profiles.
        settings.CODE_SIGN_STYLE = 'Automatic';
        if (marketingVersion) settings.MARKETING_VERSION = marketingVersion;
        if (buildNumber) settings.CURRENT_PROJECT_VERSION = buildNumber;
      }

      // Xcode also keeps a per-target ProvisioningStyle in the project's TargetAttributes.
      // expo-widgets never writes one for the extension; without it Xcode can decide the
      // target is manually signed regardless of CODE_SIGN_STYLE.
      // addTargetAttribute indexes TargetAttributes by `target.uuid`, and the objects
      // getNativeTargets yields do NOT carry their own uuid (it is the map key), so it has
      // to be handed a { uuid } wrapper or it writes under the literal key "undefined".
      project.addTargetAttribute('ProvisioningStyle', 'Automatic', { uuid: targetUuid });
      project.addTargetAttribute('DevelopmentTeam', appleTeamId, { uuid: targetUuid });

      touched.push(unquote(target.name));
    }

    if (!touched.some((name) => name === 'ExpoWidgetsTarget')) {
      // Loud, but not fatal: a widget-less build is still shippable, and prebuild --clean
      // ordering issues should be visible rather than silent.
      console.warn(
        '[with-signing-and-versioning] ExpoWidgetsTarget was not in the project when this ' +
          'plugin ran, so the widget extension has no DEVELOPMENT_TEAM. This plugin must be ' +
          'listed BEFORE expo-widgets in app.json "plugins" (Expo runs mods last-registered-' +
          'first, so earlier in the array means later at runtime).'
      );
    } else {
      console.log(
        `[with-signing-and-versioning] DEVELOPMENT_TEAM=${appleTeamId} on: ${touched.join(', ')}`
      );
    }

    return cfg;
  });
};

module.exports = withSigningAndVersioning;
